let r, clrs, poss, strs;

function setup() {
	const minWH = max(windowWidth, windowHeight);
	createCanvas(minWH, minWH);
	pixelDensity(1);
	clrs = [color(192, 32, 160), color(32, 192, 160), color(192, 160, 32)];
	strs = ["!\"§$%&/()=?+*#,.-;:_", "0123456789", "abcdefghijklmnopqrstuvwxyz"];

	r = max(width, height) * 0.25;
	const n = 3;
	poss = [];
	for (let i = 0, a = -HALF_PI; i < n; i++, a += TWO_PI / n) {
		const x = cos(a) * r;
		const y = sin(a) * r;
		poss.push({x, y, i});
	}
	noStroke();
	background(0, 0, 8);
}

function mousePressed() {
	if (mouseButton == LEFT) setup();
}
function windowResized() {
	setup();
}

function draw() {
	blendMode(BLEND)
	//background(0, 0, 8, 8);
	blendMode(ADD)

	drawRandPoint();
	translate(width * 0.5, height * 0.5);
	for (let p of poss) {
		push();
		translate(p.x, p.y);
		let clr = random(clrs);
		clr.setAlpha(random(32, 160));
		stroke(clr)
		fill(clr)
		drawCirclePoint(p, r);
		pop();
	}
}

function drawCirclePoint(p, maxr) {
	push();
	let a = random(TWO_PI)
	let l = random();
	l = (1 - pow(l, p.i + 1)) * maxr;
	let vec = createVector(l, 0).setHeading(a);
	// line(0, 0, vec.x, vec.y);
	strokeWeight(floor(random(1, 4)))
	noStroke();
	// point(vec.x, vec.y);
	textAlign(CENTER, CENTER);
	chr = strs[p.i][floor(random(strs[p.i].length))];
	translate(vec.x, vec.y);
	rotate(random(TWO_PI))
	text(chr, 0, 0);
	pop();
}

function drawRandPoint() {
	var x = random(width)
	var y = random(height)
	stroke(random(100, 255));
	strokeWeight(floor(random(1, 4)))
	point(x, y);
}
